// Some portions generated by Claude
/**
 * "Expand by relation" loads every link of the chosen relation that the graph does not hold yet. Above
 * RELATION_CONFIRM_LINKS of them it asks first, and the user chooses how many to load: in total (shared evenly across
 * the selected nodes) or per node.
 */
import type { Direction } from "./explorer-types.ts";
import type { Graph } from "./graph-types.ts";
import { linkCountCap, loadedLinksOf } from "./link-counts.ts";
import type { LoadedLinks } from "./rdf-vocabulary.ts";

/** More new links than this, across the selection, are only loaded once the user says how many. */
export const RELATION_CONFIRM_LINKS = 100;

export type RelationAmount = { mode: "total" | "perNode"; amount: number };

/**
 * The new links of the relation per node (nodes without any left out) and their sum. Nodes counted past the cap
 * (`capped`) have at least that many; then the sum is a lower bound too (`atLeast`).
 */
export type RelationPlan = { available: Map<string, number>; total: number; atLeast: boolean; capped: Set<string> };

/** The links of `predicate` each node already has in the graph, and those links as Expand leaves them out. */
export function loadedRelationLinks(graph: Graph, ids: readonly string[], predicate: string, direction: Direction) {
  const counts = new Map(ids.map((id) => [id, 0]));
  for (const edge of graph.edges) {
    if (edge.predicate !== predicate) continue;
    const id = direction === "outgoing" ? edge.source : edge.target;
    const count = counts.get(id);
    if (count !== undefined) counts.set(id, count + 1);
  }
  return { counts, loaded: loadedLinksOf(graph, ids) as Map<string, LoadedLinks> };
}

/**
 * Each node's links in the repository (counted up to `cap + 1`) less the ones the graph holds. A count past the cap
 * only says "at least".
 */
export function relationPlan(
  counts: ReadonlyMap<string, number>,
  loadedCounts: ReadonlyMap<string, number>,
  cap: number,
): RelationPlan {
  const available = new Map<string, number>();
  const capped = new Set<string>();
  let total = 0;
  for (const [id, count] of counts) {
    const links = Math.max(0, count - (loadedCounts.get(id) ?? 0));
    if (!links) continue;
    if (count > cap) capped.add(id);
    available.set(id, links);
    total += links;
  }
  return { available, total, atLeast: capped.size > 0, capped };
}

/**
 * The number of links to load per node. Per node: each node up to the amount. In total: shared evenly, so nodes with
 * few links load all of them and the others split the rest; what does not divide evenly goes to the nodes with the
 * most links. Nodes in `capped` may have more links than `available` says, so only the amount bounds them. Nodes that
 * load nothing are left out.
 */
export function relationLimits(
  available: ReadonlyMap<string, number>,
  choice: RelationAmount,
  capped: ReadonlySet<string> = new Set(),
): Map<string, number> {
  const amount = Number.isFinite(choice.amount) ? Math.max(0, Math.floor(choice.amount)) : 0;
  const limits = new Map<string, number>();
  if (!amount) return limits;
  const bound = (id: string, links: number) => (capped.has(id) ? Number.POSITIVE_INFINITY : links);
  if (choice.mode === "perNode") {
    for (const [id, links] of available) limits.set(id, Math.min(bound(id, links), amount));
    return limits;
  }
  const order = [...available.keys()];
  const ascending = [...available].map(([id, links]) => [id, bound(id, links)] as const).sort((left, right) => left[1] - right[1]);
  let remaining = amount;
  let index = 0;
  for (; index < ascending.length; index++) {
    const [id, links] = ascending[index];
    if (links * (ascending.length - index) > remaining) break;
    limits.set(id, links);
    remaining -= links;
  }
  const rest = ascending.slice(index);
  if (rest.length) {
    const share = Math.floor(remaining / rest.length);
    const extra = new Set(
      [...rest]
        .sort((left, right) => right[1] - left[1] || order.indexOf(left[0]) - order.indexOf(right[0]))
        .slice(0, remaining - share * rest.length)
        .map(([id]) => id),
    );
    for (const [id] of rest) {
      const limit = share + (extra.has(id) ? 1 : 0);
      if (limit) limits.set(id, limit);
    }
  }
  // In the order of the selection, as the query asks for them.
  return new Map(order.flatMap((id) => (limits.has(id) ? [[id, limits.get(id)!] as const] : [])));
}

/**
 * How far to count each node's links: `base` past the most links of a node the graph already holds, so that loaded
 * links never use up the count and make the rest look loaded.
 */
export function relationCountCap(loadedCounts: ReadonlyMap<string, number>, base: number) {
  return linkCountCap(Math.max(0, ...loadedCounts.values()), base);
}

/** At most this many nodes in one query. */
const NODES_PER_QUERY = 64;

/**
 * The nodes in groups of one query each, in selection order, so that no query asks for more rows than the server
 * sends (`maxRows`, which it cuts at without saying so): a group closes when the next node's expected rows would not
 * fit. A node expecting more than `maxRows` goes alone.
 */
export function relationChunks(ids: readonly string[], expected: ReadonlyMap<string, number>, maxRows: number | undefined) {
  const chunks: string[][] = [];
  let chunk: string[] = [];
  let rows = 0;
  for (const id of ids) {
    const wanted = expected.get(id) ?? 0;
    if (chunk.length && (chunk.length >= NODES_PER_QUERY || (maxRows !== undefined && rows + wanted > maxRows))) {
      chunks.push(chunk);
      chunk = [];
      rows = 0;
    }
    chunk.push(id);
    rows += wanted;
  }
  if (chunk.length) chunks.push(chunk);
  return chunks;
}
